---Fill
---填充数据
---@param jsonData table
---@return CardDojo
function CardDojo:Fill(jsonData)
    for key, value in pairs(jsonData) do
        --只更新自己关心的数据
        if isSet(jsonData,key) and table.haskey(self,key) then
            if type(value) == "function" then
                self[key] = checkString(value)
            else
                self[key] = value
                if key == "cafeEnergy" then
                    if Events.HasListener(MaidCoff_ChangeCardEnergy) then
                        Events.Broadcast(MaidCoff_ChangeCardEnergy,self.id)
                    end
                end
            end
        end
    end
    
    local finalSkillLevel = checkNumber(self.finalSkillLevel)
    local awakeningLevel  = checkNumber(self.awakeningLevel)
    self.finalSkillLevel  = finalSkillLevel <= 0 and 1 or finalSkillLevel
    self.awakeningLevel   = awakeningLevel <= 0 and 1 or awakeningLevel

    return self
end

function CardDojo:GetRare()
