end

function CardDojo:GetFavorLv2ReceivedRes()
    if self.favorLv2ReceivedRes == nil then
        local receivedList = string.split2(self.favorRewardsReceived, ",") or {}
        ---有的话 新建 table 空表直接用它
        local t = next(receivedList) ~= nil and {} or receivedList
        for i, v in ipairs(receivedList) do
            t[checkNumber(v)] = true
        end
        self.favorLv2ReceivedRes = t
        
    end
    return self.favorLv2ReceivedRes
end

function CardDojo:AddFavorLv2ReceivedRes(lv)
    local lv2res = self:GetFavorLv2ReceivedRes()
    lv2res[checkNumber(lv)] = true
end

function CardDojo:GetStoryId2ReceivedRes()
